Syntax check passed. The struct holds the heap-allocated counters in a `Vec<u64>`, and `histogram_free` drops the whole box via `Box::from_raw`, so every byte `histogram_new` touched is returned.

```rust
pub struct Histogram {
    bins: Vec<u64>,
}

impl Histogram {
    fn new(bins: u32) -> Option<Box<Self>> {
        (bins != 0).then(|| {
            let counters = vec![0u64; bins as usize];
            Some(Box::new(Histogram { bins: counters }))
        })
    }
}

#[no_mangle]
pub extern "C" fn histogram_new(bins: u32) -> *mut Histogram {
    Histogram::new(bins).map_or(std::ptr::null_mut(), Box::into_raw)
}

#[no_mangle]
pub unsafe extern "C" fn histogram_add(h: *mut Histogram, bin: u32) -> i32 {
    if h.is_null() {
        return -1;
    }
    let histogram = unsafe { &mut *h };
    if bin as usize >= histogram.bins.len() {
        return -2;
    }
    unsafe {
        histogram.bins[bin as usize] += 1;
    }
    0
}

#[no_mangle]
pub unsafe extern "C" fn histogram_count(h: *const Histogram, bin: u32) -> u64 {
    if h.is_null() {
        return 0;
    }
    let histogram = unsafe { &*h };
    if bin as usize >= histogram.bins.len() {
        return 0;
    }
    histogram.bins[bin as usize]
}

#[no_mangle]
pub unsafe extern "C" fn histogram_free(h: *mut Histogram) {
    if h.is_null() {
        return;
    }
    Box::from_raw(h);
}
